["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Arator says: Orweyna... what was that thing?",
["id"] = "s0_2860",
["timestamp"] = 1772214238,
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
