["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Arator says: The mist ward is gone! Let's find Zul'jan.",
["id"] = "s0_3366",
["timestamp"] = 1772226861,
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
