["r"] = 0,
},
["text"] = "You receive item: |cnIQ2:|Hitem:252677::::::::82:263::11:2:13573:6652:2:9:82:28:3085:::::|h[Puzzling Crypt Relic]|h|r",
["id"] = "s0_3369",
