},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Arator says: We have to find Zul'jan before it's too late.",
["id"] = "s0_3370",
["timestamp"] = 1772226965,
},
