["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Lor'themar Theron says: Lady Liadrin, secure the pass. For good or ill, we've taken a stand here. We should keep it.",
["id"] = "s0_3410",
["timestamp"] = 1772235949,
},
