},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Aradis says: We meet again, Kvotheen. And with a new rat to replace the ones you released. How thoughtful.",
["timestamp"] = 1772275616,
["id"] = "s0_3929",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Magister Aradis",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
