},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Magister Aradis says: I... deserved... better...",
["timestamp"] = 1772275626,
["id"] = "s0_3932",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Jaeth",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Jaeth says: Nngh--I wish I got the kill... But at least he's dead.",
["timestamp"] = 1772275627,
["id"] = "s0_3933",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
