},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0,
},
["text"] = "You loot 2 Gold, 16 Silver, 30 Copper (+4 Silver, 32 Copper)",
["timestamp"] = 1772275628,
["id"] = "s0_3934",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Jaeth",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Jaeth says: I need to check on the others. Meet me upstairs after you take whatever you want from his corpse.",
["timestamp"] = 1772275632,
["id"] = "s0_3935",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
