},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Valeera Sanguinar says: I'll handle the lock. You deal with the trap.",
["id"] = "s0_4120",
["timestamp"] = 1772277059,
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Valeera Sanguinar",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
