},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Loa Speaker Kinduru says: Just a minute now, Jan-boy.",
["id"] = "s0_4184",
["timestamp"] = 1772277818,
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
