},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Loa Speaker Kinduru says: I need my staff. Akil'zon will never grant me favor again if I abandon de staff in battle!",
["id"] = "s0_4185",
["timestamp"] = 1772277874,
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
