},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Zul'jan says: Old man, de loa stopped granting us favor decades ago. And we are better off without them.",
["id"] = "s0_4186",
["timestamp"] = 1772277882,
},
{
["recordedBy"] = "Kvotheen-Hyjal",
