["name"] = "Kahanea",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Kahanea says: I'll meet you near de top of de Prowl, Kvotheen. We will get to de bottom of dis!",
