["typeInfo"] = {
["player"] = {
["name"] = "Kovu",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Kovu says: Wait, I think I feel de rhythm.",
["timestamp"] = 1772291637,
["id"] = "s0_4509",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Kovu",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Kovu says: I've got it! I'm dancin'!",
["timestamp"] = 1772291639,
["id"] = "s0_4510",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
