},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "An'jali says: Oh, hi! Welcome back! Did you find dem all?",
["timestamp"] = 1772292048,
["id"] = "s0_4555",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
