},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "An'jali says: ...Yes, Papa.",
["timestamp"] = 1772292060,
["id"] = "s0_4557",
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Ani",
},
