["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Mixer Jamanga says: Shadra, de Witherbark are honored to have you back among us.",
["timestamp"] = 1772327608,
["id"] = "s1_3188",
},
