},
["text"] = "|Hchannel:GUILD|h[Guild]|h |Hplayer:Dordok-Ysondre:37:GUILD:|h[|cffaad372Dordok-Ysondre|r]|h: PTIN!",
["id"] = "s1_3246",
["timestamp"] = 1772356694,
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["race"] = "Orc",
["class"] = "HUNTER",
["name"] = "Dordok-Ysondre",
