},
["color"] = {
["b"] = 0.6235294342041016,
["g"] = 1,
["r"] = 1,
},
["text"] = "Zur'ashar Kassameh says: We learned the shape of the beasts.",
["id"] = "s1_3596",
["timestamp"] = 1772385684,
},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["name"] = "Zur'ashar Kassameh",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
