["g"] = 1,
["r"] = 1,
},
["text"] = "Orweyna says: I'm ready to perform the Shul'ka's ritual. It will protect us when we enter the Rift of Aln... for a time.",
["id"] = "s1_3843",
["timestamp"] = 1772389853,
},
