},
{
["recordedBy"] = "Kvotheen-Hyjal",
["typeInfo"] = {
["player"] = {
["class"] = "PALADIN",
["race"] = "Human",
["name"] = "Delondra-LaCroisadeécarlate",
["sex"] = 3,
},
["event"] = "CHAT_MSG_GUILD",
